SELECT count(*) AS r208, min(n.id) AS lo, max(n.id) AS hi, sum((SELECT count(*) FROM notice_sections s WHERE s.kind = 'Change' AND s.notice_id = n.id)) AS chg_sections, sum(EXISTS (SELECT 1 FROM notice_sections s WHERE s.kind = 'Change' AND s.notice_id = n.id)) AS chg_notices, sum(EXISTS (SELECT 1 FROM notice_codes c WHERE c.notice_id = n.id AND c.section_id = 'PROCEDURE' AND c.field_id = 'TED-FORM')) AS has_form, sum(EXISTS (SELECT 1 FROM notice_codes c WHERE c.notice_id = n.id AND c.section_id = 'PROCEDURE' AND c.field_id = 'TED-FORM' AND c.code = '14')) AS f14, sum(EXISTS (SELECT 1 FROM notice_ids i WHERE i.notice_id = n.id AND i.section_id = 'PROCEDURE' AND i.field_id = 'TED-CA_CE_CONCESSIONAIRE_PROFILE' AND i.ordinal = 0)) AS cace0, sum(EXISTS (SELECT 1 FROM notice_ids i WHERE i.notice_id = n.id AND i.field_id = 'TED-CA_CE_CONCESSIONAIRE_PROFILE' AND (i.ordinal > 0 OR i.section_id <> 'PROCEDURE'))) AS cace_x FROM notices n WHERE +n.profile = 'ted-export-r208' AND n.id BETWEEN 18760001 AND 18845000
